def normalized_spell_entry(
    spell: SpellEntry,
    *,
    source: SpellSource,
    casting_ability: AbilityType,
) -> SpellEntry:
    return replace(
        spell,
        status=SpellStatus(
            source=source,
            castingAbility=casting_ability,
            resourceId=spell.resourceId,
            reset=spell.reset,
        ),
        components=list(spell.components),
        mechanics=deepcopy(spell.mechanics),
    )


def clone_spell_entry(spell: SpellEntry) -> SpellEntry:
    return replace(
        spell,
        components=list(spell.components),
        status=replace(spell.status),
        mechanics=deepcopy(spell.mechanics),
    )


def spell_description(metadata: SpellCatalogMetadata, spell: SpellEntry) -> str:
    casting_label = metadata.castingDuration.summary if metadata.castingDuration is not None else enum_label(spell.castingTime)
    range_label = spell.targeting.summary
    components_label = ", ".join(enum_label(component) for component in spell.components) if spell.components else "None"
    duration_label = spell.duration.summary
    details = [
        f"Spell lists: {', '.join(spell_list.value for spell_list in metadata.spellLists)}.",
        f"Casting time: {casting_label}.",
        f"Range: {range_label}.",
        f"Components: {components_label}.",
        f"Duration: {duration_label}.",
    ]
    if metadata.triggered:
        details.append("Casting has a special trigger.")
    if metadata.materialCost:
        details.append("Material component has a listed cost.")
    if metadata.materialConsumed:
        details.append("Material component is consumed.")
    return " ".join(details)



@dataclass(frozen=True)
class SpellCatalogRecord:
    entry: SpellEntry
    spellLists: tuple[SpellListType, ...]
    url: str
    triggered: bool = False
    material: bool = False
    materialCost: bool = False
    materialConsumed: bool = False


def spell_metadata_from_record(record: SpellCatalogRecord) -> SpellCatalogMetadata:
    return SpellCatalogMetadata(
        spellId=record.entry.id,
        spellLists=record.spellLists,
        url=record.url,
        castingDuration=record.entry.castingDuration,
        triggered=record.triggered,
        material=record.material,
        materialCost=record.materialCost,
        materialConsumed=record.materialConsumed,
    )


def spell_entry_from_record(record: SpellCatalogRecord) -> SpellEntry:
    metadata = spell_metadata_from_record(record)
    spell = clone_spell_entry(record.entry)
    return replace(spell, description=spell_description(metadata, spell))


def build_spell_catalog(records: tuple[SpellCatalogRecord, ...]) -> dict[SpellId, SpellEntry]:
    return {record.entry.id: spell_entry_from_record(record) for record in records}


def build_spell_metadata(records: tuple[SpellCatalogRecord, ...]) -> dict[SpellId, SpellCatalogMetadata]:
    return {record.entry.id: spell_metadata_from_record(record) for record in records}


def saving_throw_damage_mechanics(
    dice_count: int,
    dice_type: DiceType,
    damage_type: DamageType,
    saving_throw: AbilityType,
) -> FeatureMechanics:
    scaling = [AmountScaling(
        basis=ScalingBasis.SPELL_SLOT_LEVEL,
        interval=1,
        additionalDice=DiceAmount(1, dice_type),
    )]
    return FeatureMechanics(activatedEffects=[
        SavingThrowEffect(
            savingThrow=SavingThrow(
                saving_throw,
                DifficultyClass(DifficultyClassType.SOURCE_SPELL_SAVE_DC),
            ),
            onFailure=ApplyEffect(DamageEffect(
                amount=DiceAmount(dice_count, dice_type),
                damageType=damage_type,
                scaling=scaling,
            )),
            onSuccess=ApplyEffect(DamageEffect(
                amount=DiceAmount(dice_count, dice_type),
                damageType=damage_type,
                scaling=scaling,
                multiplierNumerator=1,
                multiplierDenominator=2,
            )),
        )
    ])


def spellcasting_healing_mechanics(dice_count: int, dice_type: DiceType) -> FeatureMechanics:
    return FeatureMechanics(activatedEffects=[
        ApplyEffect(HealingEffect(
            amount=CombinedAmount([
                DiceAmount(dice_count, dice_type),
                CalculatedAmount(AmountCalculation.SOURCE_SPELLCASTING_MODIFIER),
            ]),
            scaling=[AmountScaling(
                basis=ScalingBasis.SPELL_SLOT_LEVEL,
                interval=1,
                additionalDice=DiceAmount(dice_count, dice_type),
            )],
        ))
    ])


def cantrip_damage_scaling(dice_type: DiceType, dice_count: int = 1) -> list[AmountScaling]:
    return [AmountScaling(
        basis=ScalingBasis.CHARACTER_LEVEL,
        interval=1,
        additionalDice=DiceAmount(dice_count, dice_type),
        thresholds=[5, 11, 17],
    )]


def spell_attack_damage_mechanics(
    dice_count: int,
    dice_type: DiceType,
    damage_type: DamageType,
    *,
    scaling: list[AmountScaling] | None = None,
    additional_on_hit: list[EffectNode] | None = None,
    bonus_spellcasting_ability: bool = False,
) -> FeatureMechanics:
    amount = DiceAmount(dice_count, dice_type)
    effect_amount = CombinedAmount([amount, CalculatedAmount(AmountCalculation.SOURCE_SPELLCASTING_MODIFIER)]) if bonus_spellcasting_ability else amount
    damage = ApplyEffect(DamageEffect(
        amount=effect_amount,
        damageType=damage_type,
        scaling=scaling or [],
    ))
    on_hit: EffectNode = damage
    if additional_on_hit:
        on_hit = SequenceEffect([damage, *additional_on_hit])
    return FeatureMechanics(activatedEffects=[
        AttackRollEffect(
            attack=AttackRoll(AttackRollType.SPELL),
            onHit=on_hit,
        )
    ])


def spell_attack_damage_choice_mechanics(
    dice_count: int,
    dice_type: DiceType,
    damage_types: tuple[DamageType, ...],
    *,
    scaling: list[AmountScaling] | None = None,
) -> FeatureMechanics:
    return FeatureMechanics(activatedEffects=[ChoiceEffect(choices=[
        EffectChoice(
            option=damage_type,
            effect=spell_attack_damage_mechanics(
                dice_count,
                dice_type,
                damage_type,
                scaling=scaling,
            ).activatedEffects[0],
        )
        for damage_type in damage_types
    ])])


def repeated_spell_attack_damage_mechanics(
    dice_count: int,
    dice_type: DiceType,
    damage_type: DamageType,
    instances: InstanceScaling,
) -> FeatureMechanics:
    attack = spell_attack_damage_mechanics(dice_count, dice_type, damage_type).activatedEffects[0]
    return FeatureMechanics(activatedEffects=[RepeatedEffect(instances=instances, effect=attack)])


def saving_throw_damage_node(
    dice_count: int,
    dice_type: DiceType,
    damage_type: DamageType,
    saving_throw: AbilityType,
    *,
    half_damage_on_success: bool = False,
    scaling: list[AmountScaling] | None = None,
    additional_on_failure: list[EffectNode] | None = None,
) -> SavingThrowEffect:
    damage = DamageEffect(
        amount=DiceAmount(dice_count, dice_type),
        damageType=damage_type,
        scaling=scaling or [],
    )
    failure: EffectNode = ApplyEffect(damage)
    if additional_on_failure:
        failure = SequenceEffect([failure, *additional_on_failure])
    success = None
    if half_damage_on_success:
        success = ApplyEffect(replace(damage, multiplierNumerator=1, multiplierDenominator=2))
    return SavingThrowEffect(
        savingThrow=SavingThrow(
            saving_throw,
            DifficultyClass(DifficultyClassType.SOURCE_SPELL_SAVE_DC),
        ),
        onFailure=failure,
        onSuccess=success,
    )


def spell_attack_with_followup_mechanics(
    dice_count: int,
    dice_type: DiceType,
    damage_type: DamageType,
    followup: EffectNode,
    *,
    scaling: list[AmountScaling] | None = None,
) -> FeatureMechanics:
    hit_damage = ApplyEffect(DamageEffect(
        amount=DiceAmount(dice_count, dice_type),
        damageType=damage_type,
        scaling=scaling or [],
    ))
    return FeatureMechanics(activatedEffects=[AttackRollEffect(
        attack=AttackRoll(AttackRollType.SPELL),
        onHit=SequenceEffect([hit_damage, followup]),
        onMiss=followup,
    )])


def saving_throw_condition_mechanics(
    conditions: tuple[ConditionType, ...],
    saving_throw: AbilityType,
) -> FeatureMechanics:
    condition_effects = [ApplyEffect(ConditionChangeEffect(condition, ConditionOperation.ADD)) for condition in conditions]
    on_failure: EffectNode = condition_effects[0] if len(condition_effects) == 1 else SequenceEffect(condition_effects)
    return FeatureMechanics(activatedEffects=[SavingThrowEffect(
        savingThrow=SavingThrow(saving_throw, DifficultyClass(DifficultyClassType.SOURCE_SPELL_SAVE_DC)),
        onFailure=on_failure,
    )])


