SPELL_CATALOG = build_spell_catalog(SPELL_CATALOG_RECORDS)
SPELL_METADATA = build_spell_metadata(SPELL_CATALOG_RECORDS)


def wizard_spell_entry(value: str | SpellId, *, casting_ability: AbilityType = AbilityType.INTELLIGENCE) -> SpellEntry | None:
    return spell_entry_for_list(value, SpellListType.WIZARD, source=SpellSource.WIZARD, casting_ability=casting_ability)


def wizard_spell_entries(*, maximum_level: int | None = None, exact_level: int | None = None, schools: set[SpellSchool] | None = None, casting_ability: AbilityType = AbilityType.INTELLIGENCE) -> list[SpellEntry]:
    return spell_entries_for_list(SpellListType.WIZARD, maximum_level=maximum_level, exact_level=exact_level, schools=schools, source=SpellSource.WIZARD, casting_ability=casting_ability)


def selected_spell_entries(spells: list[SpellEntry], selected_spell_ids: list[str] | None) -> list[SpellEntry]:
    selected = set(selected_spell_ids or [])
    return [clone_spell_entry(spell) for spell in spells if enum_key(spell.id) in selected]
